def workspace(*, allow_writes=False, allowed_commands=()):
    """Day 1 prompt boundary without depending on the Day 2 workspace."""

    policy = SimpleNamespace(
        allow_writes=allow_writes,
        allowed_commands=allowed_commands,
    )
    tools = {"list_files", "read_file"}
    if allow_writes:
        tools.update({"write_file", "edit_file"})
    if allowed_commands:
        tools.add("run_command")
    return SimpleNamespace(policy=policy, available_tools=frozenset(tools))


def test_task_1_parse_final_action():
    assert parse_action('{"final":"done"}') == FinalAction("done")


@pytest.mark.parametrize(
    ("response", "expected"),
    [
        ('{"tool":"list_files"}', ToolAction("list_files", {})),
        (
            '{"tool":"list_files","path":"src"}',
            ToolAction("list_files", {"path": "src"}),
        ),
        (
            '{"tool":"read_file","path":"README.md"}',
            ToolAction("read_file", {"path": "README.md"}),
        ),
        (
            '{"tool":"write_file","path":"x","content":"y"}',
            ToolAction("write_file", {"path": "x", "content": "y"}),
        ),
        (
            '{"tool":"edit_file","path":"x","old":"a","new":"b"}',
            ToolAction("edit_file", {"path": "x", "old": "a", "new": "b"}),
        ),
        (
            '{"tool":"run_command","argv":["pdm","run","test"]}',
            ToolAction("run_command", {"argv": ["pdm", "run", "test"]}),
        ),
    ],
)
def test_task_1_parse_every_tool_schema(response, expected):
    assert parse_action(response) == expected


