def bounded_workspace(
    root: Path,
    *,
    allow_writes: bool = False,
    allowed_commands: tuple[tuple[str, ...], ...] = (),
    confirm_tool=None,
    command_timeout_seconds: float = 1.0,
) -> Workspace:
    """Build the real Day 2 workspace used by the cumulative checkpoint."""

    return Workspace(
        ToolPolicy(
            root,
            allow_writes=allow_writes,
            allowed_commands=allowed_commands,
            command_timeout_seconds=command_timeout_seconds,
        ),
        confirm_tool=confirm_tool,
    )


def test_task_4_paths_fail_closed_for_escapes_symlinks_and_secrets(tmp_path):
    root = tmp_path / "workspace"
    root.mkdir()
    outside = tmp_path / "outside.txt"
    outside.write_text("outside", encoding="utf-8")
    (root / "visible.txt").write_text("visible", encoding="utf-8")
    (root / ".env").write_text("TOKEN=secret", encoding="utf-8")
    (root / "private.key").write_text("secret", encoding="utf-8")
    (root / ".git").mkdir()
    (root / ".git" / "config").write_text("secret", encoding="utf-8")
    (root / "link.txt").symlink_to(outside)
    (root / "internal-link.txt").symlink_to(root / "visible.txt")
    ws = bounded_workspace(root)

    assert ws.read_file("visible.txt") == "visible"
    for path in (
        "../outside.txt",
        ".env",
        "private.key",
        ".git/config",
        "link.txt",
        "internal-link.txt",
    ):
        with pytest.raises(AgentError):
            ws.read_file(path)
    listing = ws.list_files()
    assert "visible.txt" in listing
    assert ".env" not in listing
    assert ".git" not in listing
    assert "link.txt" not in listing
    assert "internal-link.txt" not in listing


def test_task_4_root_identity_swap_never_reads_the_replacement(tmp_path, monkeypatch):
    root = tmp_path / "workspace"
    root.mkdir()
    (root / "answer.txt").write_text("authorized", encoding="utf-8")
    replacement = tmp_path / "replacement"
    replacement.mkdir()
    (replacement / "answer.txt").write_text("replacement", encoding="utf-8")
    authorized = tmp_path / "authorized"
    ws = bounded_workspace(root)
    validate = ws._validate_root
    swapped = False

    def validate_then_swap():
        nonlocal swapped
        validate()
        if not swapped:
            root.rename(authorized)
            replacement.rename(root)
            swapped = True

    monkeypatch.setattr(ws, "_validate_root", validate_then_swap)
    with pytest.raises(AgentError, match="root changed"):
        ws.read_file("answer.txt")
    assert (root / "answer.txt").read_text(encoding="utf-8") == "replacement"


def test_task_4_root_swap_during_approval_never_writes_replacement(tmp_path):
    root = tmp_path / "workspace"
    root.mkdir()
    (root / "answer.txt").write_text("authorized", encoding="utf-8")
    replacement = tmp_path / "replacement"
    replacement.mkdir()
    (replacement / "answer.txt").write_text("replacement", encoding="utf-8")
    authorized = tmp_path / "authorized"

    def swap_root(_action):
        root.rename(authorized)
        replacement.rename(root)
        return True

    ws = bounded_workspace(root, allow_writes=True, confirm_tool=swap_root)
    assert ws.read_file("answer.txt") == "authorized"
    result = ws.execute(
        ToolAction("write_file", {"path": "answer.txt", "content": "changed"}),
        tool_call_id="root-write-race",
    )
    assert "root changed" in result
    assert (root / "answer.txt").read_text(encoding="utf-8") == "replacement"
    assert (authorized / "answer.txt").read_text(encoding="utf-8") == "authorized"


def test_task_5_overwrite_requires_a_fresh_inspection(tmp_path):
    root = tmp_path / "workspace"
    root.mkdir()
    target = root / "answer.txt"
    target.write_text("one", encoding="utf-8")
    ws = bounded_workspace(root, allow_writes=True)

    with pytest.raises(AgentError, match="read before overwrite"):
        ws.write_file("answer.txt", "two")
    assert ws.read_file("answer.txt") == "one"
    target.write_text("changed elsewhere", encoding="utf-8")
    with pytest.raises(AgentError, match="changed since it was read"):
        ws.write_file("answer.txt", "two")
    assert target.read_text(encoding="utf-8") == "changed elsewhere"


def test_task_6_preflight_precedes_approval_and_commit_revalidates(tmp_path):
    root = tmp_path / "workspace"
    root.mkdir()
    target = root / "answer.txt"
    target.write_text("one", encoding="utf-8")
    approvals = []

    def mutate_during_approval(action):
        approvals.append(action.tool)
        target.write_text("changed during approval", encoding="utf-8")
        return True

    ws = bounded_workspace(root, allow_writes=True, confirm_tool=mutate_during_approval)
    result = ws.execute(
        ToolAction("write_file", {"path": "answer.txt", "content": "two"}),
        tool_call_id="invalid-before-approval",
    )
    assert result.startswith("error:")
    assert approvals == []

    ws.read_file("answer.txt")
    result = ws.execute(
        ToolAction("write_file", {"path": "answer.txt", "content": "two"}),
        tool_call_id="race-after-approval",
    )
    assert result.startswith("error:")
    assert approvals == ["write_file"]
    assert target.read_text(encoding="utf-8") == "changed during approval"


