def test_task_7_command_allowlist_is_exact_and_approval_is_required(tmp_path):
    root = tmp_path / "workspace"
    root.mkdir()
    allowed = (sys.executable, "-c", "print('allowed')")
    failing = (
        sys.executable,
        "-c",
        "import sys; print('failed'); sys.exit(3)",
    )
    approvals = []
    ws = bounded_workspace(
        root,
        allowed_commands=(allowed, failing),
        confirm_tool=lambda action: approvals.append(action) or True,
    )

    rejected = ws.execute(
        ToolAction("run_command", {"argv": [*allowed, "extra"]}),
        tool_call_id="not-exact",
    )
    assert "not explicitly allowed" in rejected
    assert approvals == []

    result = ws.execute(
        ToolAction("run_command", {"argv": list(allowed)}),
        tool_call_id="exact-command",
    )
    assert "allowed" in result
    assert "[exit code: 0]" in result
    assert len(approvals) == 1

    result = ws.execute(
        ToolAction("run_command", {"argv": list(failing)}),
        tool_call_id="failed-command",
    )
    assert "failed" in result
    assert "command exited with code 3" in result
    assert ws.last_receipt is not None
    assert ws.last_receipt.exit_state == "error"
    assert len(approvals) == 2


