def test_task_7_closed_pipes_cannot_escape_the_process_deadline(tmp_path):
    root = tmp_path / "workspace"
    root.mkdir()
    command = (
        sys.executable,
        "-c",
        "import os,time,pathlib; os.close(1); os.close(2); time.sleep(0.6); "
        "pathlib.Path('late.txt').write_text('late')",
    )
    ws = bounded_workspace(
        root,
        allowed_commands=(command,),
        confirm_tool=lambda _action: True,
        command_timeout_seconds=0.1,
    )

    started = time.monotonic()
    result = ws.execute(
        ToolAction("run_command", {"argv": list(command)}),
        tool_call_id="closed-pipes-timeout",
    )
    elapsed = time.monotonic() - started
    assert elapsed < 1.0
    assert "timed out after" in result
    assert ws.last_receipt is not None
    assert ws.last_receipt.exit_state == "uncertain"
    time.sleep(0.7)
    assert not (root / "late.txt").exists()


def test_task_8_receipts_are_detached_immutable_and_content_addressed():
    arguments = {"path": "answer.txt", "metadata": ["one"]}
    receipt = EffectReceipt(
        tool_call_id="call-1",
        tool="write_file",
        arguments=arguments,
        exit_state="ok",
        result="wrote answer.txt",
        changed_artifacts=("answer.txt",),
    )
    receipt_id = receipt.receipt_id
    arguments["metadata"].append("mutated")

    assert receipt.receipt_id == receipt_id
    assert receipt.to_dict()["arguments"]["metadata"] == ["one"]
    with pytest.raises(TypeError):
        receipt.arguments["path"] = "other.txt"
    with pytest.raises(AttributeError):
        receipt.arguments["metadata"].append("other")
    durable = receipt.to_dict()
    durable["result"] = "tampered"
    with pytest.raises(ValueError, match="digest"):
        EffectReceipt.from_dict(durable)


def test_task_8_receipt_store_is_durable_and_rejects_tampering(tmp_path):
    path = tmp_path / "receipts.jsonl"
    receipt = EffectReceipt(
        tool_call_id="call-2",
        tool="read_file",
        arguments={"path": "answer.txt"},
        exit_state="ok",
        result="answer",
        changed_artifacts=(),
    )
    store = ReceiptStore(path)
    receipt_id = store.put(receipt)
    assert store.put(receipt) == receipt_id
    assert len(store) == 1

    reopened = ReceiptStore(path)
    assert reopened.require(receipt_id).to_dict() == receipt.to_dict()
    assert reopened.by_tool_call("call-2") == receipt
    conflicting = EffectReceipt(
        tool_call_id="call-2",
        tool="read_file",
        arguments={"path": "other.txt"},
        exit_state="ok",
        result="other",
        changed_artifacts=(),
    )
    with pytest.raises(ValueError, match="already belongs"):
        reopened.put(conflicting)

    payload = json.loads(path.read_text(encoding="utf-8"))
    payload["result"] = "tampered"
    path.write_text(json.dumps(payload) + "\n", encoding="utf-8")
    with pytest.raises(ValueError, match="invalid receipt"):
        ReceiptStore(path)


def test_task_8_two_live_stores_serialize_call_ids_and_reopen_cleanly(tmp_path):
    path = tmp_path / "receipts.jsonl"
    first = ReceiptStore(path)
    stale = ReceiptStore(path)
    receipt = EffectReceipt(
        tool_call_id="shared-call",
        tool="read_file",
        arguments={"path": "answer.txt"},
        exit_state="ok",
        result="answer",
        changed_artifacts=(),
    )
    conflict = EffectReceipt(
        tool_call_id="shared-call",
        tool="read_file",
        arguments={"path": "other.txt"},
        exit_state="ok",
        result="other",
        changed_artifacts=(),
    )

    receipt_id = first.put(receipt)
    assert stale.put(receipt) == receipt_id
    with pytest.raises(ValueError, match="already belongs"):
        stale.put(conflict)
    reopened = ReceiptStore(path)
    assert len(reopened) == 1
    assert reopened.by_tool_call("shared-call") == receipt


def test_task_9_workspace_persists_exact_changed_artifact_receipt(tmp_path):
    root = tmp_path / "workspace"
    root.mkdir()
    path = tmp_path / "receipts.jsonl"
    ws = bounded_workspace(root, allow_writes=True, confirm_tool=lambda _action: True)
    ws.bind_receipt_store(ReceiptStore(path))

    result = ws.execute(
        ToolAction("write_file", {"path": "new.txt", "content": "hello"}),
        tool_call_id="write-new",
    )
    assert result == "wrote new.txt"
    receipt = ReceiptStore(path).by_tool_call("write-new")
    assert receipt is not None
    assert receipt.exit_state == "ok"
    assert receipt.changed_artifacts == ("new.txt",)
    assert receipt.arguments == {"path": "new.txt", "content": "hello"}
    with pytest.raises(AgentError, match="already has a receipt"):
        ws.execute(
            ToolAction("write_file", {"path": "other.txt", "content": "no"}),
            tool_call_id="write-new",
        )
    assert not (root / "other.txt").exists()


def test_task_9_two_workspaces_cannot_repeat_one_durable_call_id(tmp_path):
    root = tmp_path / "workspace"
    root.mkdir()
    path = tmp_path / "receipts.jsonl"
    command = (
        sys.executable,
        "-c",
        "from pathlib import Path; p=Path('count.txt'); "
        "p.write_text(p.read_text() + 'x' if p.exists() else 'x')",
    )
    first = bounded_workspace(
        root,
        allowed_commands=(command,),
        confirm_tool=lambda _action: True,
    )
    stale = bounded_workspace(
        root,
        allowed_commands=(command,),
        confirm_tool=lambda _action: True,
    )
    first.bind_receipt_store(ReceiptStore(path))
    stale.bind_receipt_store(ReceiptStore(path))
    action = ToolAction("run_command", {"argv": list(command)})

    def dispatch(ws):
        try:
            return ws.execute(action, tool_call_id="one-effect")
        except AgentError as error:
            return str(error)

    with ThreadPoolExecutor(max_workers=2) as pool:
        results = list(pool.map(dispatch, (first, stale)))
    assert sum("exit code: 0" in result for result in results) == 1
    assert sum("already has a receipt" in result for result in results) == 1
    assert (root / "count.txt").read_text(encoding="utf-8") == "x"
    assert len(ReceiptStore(path)) == 1


def test_task_9_post_rename_fsync_failure_records_uncertain_change(
    tmp_path, monkeypatch
):
    root = tmp_path / "workspace"
    root.mkdir()
    ws = bounded_workspace(root, allow_writes=True, confirm_tool=lambda _action: True)
    real_fsync = os.fsync

    def fail_directory_fsync(descriptor):
        if stat.S_ISDIR(os.fstat(descriptor).st_mode):
            raise OSError("simulated parent fsync failure")
        return real_fsync(descriptor)

    monkeypatch.setattr(os, "fsync", fail_directory_fsync)
    result = ws.execute(
        ToolAction("write_file", {"path": "changed.txt", "content": "changed"}),
        tool_call_id="uncertain-write",
    )
    assert "durability could not be confirmed" in result
    assert (root / "changed.txt").read_text(encoding="utf-8") == "changed"
    assert ws.last_receipt is not None
    assert ws.last_receipt.exit_state == "uncertain"
    assert ws.last_receipt.changed_artifacts == ("changed.txt",)
    assert root / "changed.txt" in ws.uncertain_modified_files


