def test_task_9_policy_rejects_non_finite_timeouts(tmp_path, timeout):
    root = tmp_path / "workspace"
    root.mkdir()
    with pytest.raises(ValueError, match="positive number"):
        ToolPolicy(root, command_timeout_seconds=timeout)
